function renderSummaryChips(subject) {
  const chipsDiv = document.getElementById('i_summaryChips');
  const label = document.getElementById('i_summaryChipsLabel');
  if (!chipsDiv) return;
  chipsDiv.innerHTML = '';

  // Find best matching key
  let suggs = SUMMARY_SUGG_BY_TYPE['_default'];
  if (subject) {
    const subjectTrim = subject.trim();
    // Exact match first
    if (SUMMARY_SUGG_BY_TYPE[subjectTrim]) {
      suggs = SUMMARY_SUGG_BY_TYPE[subjectTrim];
    } else {
      // Partial match
      for (const key of Object.keys(SUMMARY_SUGG_BY_TYPE)) {
        if (key !== '_default' && (subjectTrim.includes(key) || key.includes(subjectTrim))) {
          suggs = SUMMARY_SUGG_BY_TYPE[key];
          break;
        }
      }
    }
  }

  if (label) {
    const matchedKey = subject && SUMMARY_SUGG_BY_TYPE[subject.trim()] ? `💡 اقتراحات جاهزة — ${subject.trim()}:` : '💡 اقتراحات جاهزة:';
    label.textContent = matchedKey;
  }

  suggs.forEach(s => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'suggest-chip';
    btn.textContent = s[0];
    btn.title = s[1];
    btn.onclick = () => {
      const el = document.getElementById('i_interviewSummary');
      if (el) {
        el.value = el.value.trim() ? el.value.trimEnd() + '\n' + s[1] : s[1];
        el.focus();
      }
    };
    chipsDiv.appendChild(btn);
  });
}

