function toggleArchive() {
  const body = document.getElementById('archiveBody'); const arrow = document.getElementById('archiveArrow');
  body.classList.toggle('open'); arrow.textContent = body.classList.contains('open') ? '▲' : '▼';
}

function renderArchive() {
  const archive = getArchive();
  const search = (document.getElementById('archiveSearch')?.value || '').trim().toLowerCase();
  const list = document.getElementById('archiveList');
  const countEl = document.getElementById('archiveCount');
  const statsEl = document.getElementById('archiveStats');
  if (!countEl) return;
  countEl.textContent = archive.length;
  const urgent = archive.filter(e => e.priority === 'عاجلة').length;
  statsEl.innerHTML = `<div class="archive-stat">📁 إجمالي المقابلات: <strong>${archive.length}</strong></div>${urgent ? `<div class="archive-stat" style="background:#fee2e2;border-color:#fca5a5;color:#dc2626;">🔴 حالات عاجلة: <strong>${urgent}</strong></div>` : ''}`;
  const filtered = (search ? archive.filter(e => e.studentName.toLowerCase().includes(search) || e.school.toLowerCase().includes(search)) : archive).slice();
  // ترتيب حسب تاريخ المقابلة (الأحدث أولاً) — v17: كان يستعمل الحقل a.date غير الموجود في سجلات المقابلات
  filtered.sort((a, b) => {
    const da = (a.interviewDate && a.interviewDate !== '—') ? a.interviewDate : '';
    const db = (b.interviewDate && b.interviewDate !== '—') ? b.interviewDate : '';
    return db.localeCompare(da) || ((b.id || 0) - (a.id || 0));
  });

  if (!filtered.length) { list.innerHTML = `<div class="archive-empty">${search ? '🔍 لا توجد نتائج.' : '📂 لا توجد مقابلات محفوظة بعد.<br><small>اضغط "حفظ في الأرشيف" لإضافة المقابلة الحالية.</small>'}</div>`; return; }
  const pColor = {'عاجلة':'#dc2626','عالية':'#c2410c','متوسطة':'#d97706','عادية':'#16a34a'};
  const pBg = {'عاجلة':'#fee2e2','عالية':'#fff7ed','متوسطة':'#fffbeb','عادية':'#f0fdf4'};
  // حساب عدد المقابلات لكل تلميذ
  const studentInterviewCount = {};
  archive.forEach(e => {
    const key = (e.studentName || '').trim().toLowerCase();
    if (key) studentInterviewCount[key] = (studentInterviewCount[key] || 0) + 1;
  });
  list.innerHTML = `<div style="overflow-x:auto;"><table class="archive-table"><thead><tr><th>#</th><th>اسم التلميذ(ة)</th><th>المؤسسة</th><th>المستوى</th><th>📅 تاريخ المقابلة</th><th>الأولوية</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody>${filtered.map((e,idx) => { const sKey = (e.studentName||'').trim().toLowerCase(); const count = studentInterviewCount[sKey]||1; const hasMultiple = count > 1; return `<tr><td style="text-align:center;color:var(--text-muted);font-size:0.75rem;">${idx+1}</td><td><strong style="color:var(--primary);">👤 ${e.studentName}</strong>${hasMultiple ? `<br><span style="background:#ede9fe;color:#7c3aed;border:1px solid #c4b5fd;border-radius:10px;padding:1px 7px;font-size:0.68rem;font-weight:700;">🔁 ${count} مقابلات</span>` : ''}</td><td>${e.school}</td><td style="text-align:center;">${e.level}</td><td style="text-align:center;white-space:nowrap;">📅 ${e.interviewDate}</td><td style="text-align:center;">${e.priority !== '—' ? `<span style="background:${pBg[e.priority]||'#f1f5f9'};color:${pColor[e.priority]||'#64748b'};border:1px solid ${pColor[e.priority]||'#cbd5e1'};border-radius:12px;padding:2px 9px;font-size:0.72rem;font-weight:700;">● ${e.priority}</span>` : '—'}</td><td style="text-align:center;font-size:0.75rem;">${e.currentStatus}</td><td style="white-space:nowrap;"><div style="display:flex;gap:5px;justify-content:center;flex-wrap:wrap;">${hasMultiple ? `<button class="btn-sm" style="background:linear-gradient(135deg,#7c3aed,#6d28d9);color:white;border:none;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:0.72rem;font-family:'Cairo',sans-serif;font-weight:700;" onclick="openStudentHistory('${e.studentName.replace(/'/g,"\\'")}',${e.id})" title="سجل جميع المقابلات">📋 السجل</button>` : ''}<button class="btn-sm" style="background:linear-gradient(135deg,#2563a8,#1d4ed8);color:white;border:none;border-radius:6px;padding:4px 8px;cursor:pointer;font-size:0.72rem;font-family:'Cairo',sans-serif;font-weight:700;" onclick="iLoadEntry(${e.id})" title="تحميل للتعديل">✏️ تعديل</button><button class="btn-sm btn-sm-danger" onclick="deleteFromArchive(${e.id})" title="حذف">🗑</button></div></td></tr>`; }).join('')}</tbody></table></div>`;
}

function deleteFromArchive(id) {
  if (!confirm('هل تريد حذف هذه المقابلة؟')) return;
  saveArchive(getArchive().filter(e => e.id !== id)); renderArchive(); updateDashboardStats();
}

function clearArchive() {
  const archive = getArchive();
  if (!archive.length) { alert('📂 الأرشيف فارغ بالفعل.'); return; }
  if (!confirm(`⚠️ تحذير: سيتم حذف جميع سجلات المقابلات (${archive.length} سجل) نهائياً.\n\nهل أنت متأكد من المسح الكامل؟`)) return;
  saveArchive([]); renderArchive(); updateDashboardStats();
}

function exportArchiveExcel() {
  const archive = getArchive();
  if (!archive.length) { alert('الأرشيف فارغ.'); return; }
  const headers = ['#','اسم التلميذ(ة)','المؤسسة','المستوى','تاريخ المقابلة','الجنس','درجة الأولوية','الحالة الراهنة','التوصية','المتابعة القادمة','تاريخ الحفظ'];
  const rows = archive.map((e,i) => [i+1,e.studentName,e.school,e.level,e.interviewDate,e.gender,e.priority,e.currentStatus,e.recommendation,e.nextFollowup,e.savedAt].map(cell => `"${String(cell||'').replace(/"/g,'""')}"`));
  const csv = '\uFEFF' + [headers.map(h => `"${h}"`).join(','), ...rows.map(r => r.join(','))].join('\n');
  const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([csv], {type:'text/csv;charset=utf-8;'}));
  a.download = `ارشيف_المقابلات_${new Date().toISOString().slice(0,10)}.csv`; a.click();
}

function iLoadEntry(id) {
  const entry = getArchive().find(e => e.id === id);
  if (!entry) return;
  document.querySelector('#toolInterview .main-container')?.scrollTo(0,0);
  window.scrollTo({ top: 0, behavior: 'smooth' });

  const setV = (elId, v) => { const el = document.getElementById(elId); if (el) el.value = v || ''; };
  setV('i_studentName',      entry.studentName);
  setV('i_school',           entry.school !== '—' ? entry.school : '');
  setV('i_level',            entry.level   !== '—' ? entry.level  : '');
  setV('i_interviewDate',    entry.interviewDate !== '—' ? entry.interviewDate : '');
  setV('i_interviewSubject', entry.subject !== '—' ? entry.subject : '');
  setV('i_interviewSummary', entry.summary);
  setV('i_specialist_note_text', entry.specialistNotes);
  setV('i_recommendation',  entry.recommendation);
  setV('i_next_followup',   entry.nextFollowup !== '—' ? entry.nextFollowup : '');

  const clearG = name => document.querySelectorAll(`input[name="${name}"]`).forEach(el => el.checked = false);
  const setR   = (name, v) => { const el = document.querySelector(`input[name="${name}"][value="${v}"]`); if (el) el.checked = true; };
  clearG('i_gender');   setR('i_gender',   entry.gender);
  clearG('i_semester'); setR('i_semester', entry.semester);
  clearG('i_priority'); setR('i_priority', entry.priority);
  clearG('i_current_status'); setR('i_current_status', entry.currentStatus);

  const procMap = {
    'جلسات متابعة دورية': 'i_chk_sessions',
    'أنشطة تربوية':        'i_chk_activities',
    'دعم مدرسي':           'i_chk_support',
    'إحالة أخصائي نفسي':   'i_chk_psych',
    'إحالة جمعية اضطرابات التعلم': 'i_chk_learning',
    'التواصل مع ولي الأمر': 'i_chk_parent_contact',
    'التنسيق مع الإدارة التربوية': 'i_chk_admin',
    'الإحالة على مصالح الشؤون الاجتماعية': 'i_chk_social',
    'توقيع التزام': 'i_chk_commitment',
    'الوساطة وحل النزاعات': 'i_chk_mediation'
  };
  Object.values(procMap).forEach(id => { const el = document.getElementById(id); if (el) el.checked = false; });
  (entry.procedures || []).forEach(p => {
    if (procMap[p]) { const el = document.getElementById(procMap[p]); if (el) el.checked = true; }
  });

  iRestoreProcRows(entry.procedureRows);
  iShowEditBar(id);
}

function iShowEditBar(id) {
  let bar = document.getElementById('iEditBar');
  if (!bar) {
    bar = document.createElement('div');
    bar.id = 'iEditBar';
    bar.style.cssText = 'position:sticky;top:0;z-index:200;background:linear-gradient(135deg,#1d4ed8,#2563a8);color:white;padding:12px 18px;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;border-bottom:3px solid #fcd34d;';
    bar.innerHTML = `
      <div style="display:flex;align-items:center;gap:10px;font-size:0.88rem;font-weight:700;">
        <span style="font-size:1.2rem;">✏️</span>
        <span>وضع التعديل — تم تحميل بيانات المقابلة. عدّل ما تريد ثم احفظ.</span>
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;">
        <button onclick="iUpdateEntry()" style="background:#fcd34d;color:#1a3a5c;border:none;border-radius:8px;padding:8px 16px;font-family:'Cairo',sans-serif;font-size:0.84rem;font-weight:800;cursor:pointer;">💾 حفظ التعديلات</button>
        <button onclick="iCancelEdit()" style="background:rgba(255,255,255,0.2);color:white;border:1px solid rgba(255,255,255,0.4);border-radius:8px;padding:8px 14px;font-family:'Cairo',sans-serif;font-size:0.82rem;font-weight:700;cursor:pointer;">✕ إلغاء</button>
      </div>`;
    const container = document.querySelector('#toolInterview .main-container');
    if (container) container.insertBefore(bar, container.firstChild);
  }
  bar.style.display = 'flex';
  bar.dataset.editId = id;
}

function iHideEditBar() { const b = document.getElementById('iEditBar'); if (b) b.style.display = 'none'; }

function iCancelEdit() {
  iHideEditBar();
  document.querySelectorAll('#toolInterview input[type=text], #toolInterview input[type=date], #toolInterview textarea').forEach(el => el.value = '');
  document.querySelectorAll('#toolInterview input[type=radio], #toolInterview input[type=checkbox]').forEach(el => el.checked = false);
  document.querySelectorAll('#toolInterview select').forEach(el => el.selectedIndex = 0);
  const s = document.getElementById('i_school'); if (s) s.value = getInstitutionName();
  iResetProcTable();
}

function iUpdateEntry() {
  const bar = document.getElementById('iEditBar');
  const id = bar ? parseInt(bar.dataset.editId) : null;
  if (!id) return;
  const studentName = val('i_studentName');
  if (!studentName) { alert('⚠️ يرجى إدخال اسم التلميذ(ة) أولاً.'); return; }
  const procedures = iProcNames();
  const procedureRows = iProcDetails();
  const updatedEntry = {
    id, savedAt: new Date().toLocaleString('ar-MA') + ' (معدَّل)',
    studentName, school: val('i_school') || '—', level: val('i_level') || '—',
    interviewDate: val('i_interviewDate') || '—', subject: val('i_interviewSubject') || '—',
    semester: getRadio('i_semester') || '—', gender: getRadio('i_gender') || '—',
    priority: getRadio('i_priority') || '—', currentStatus: '—',
    summary: val('i_interviewSummary') || '', specialistNotes: val('i_specialist_note_text') || '',
    procedures, procedureRows, recommendation: val('i_recommendation') || '', nextFollowup: '—'
  };
  const archive = getArchive();
  const idx = archive.findIndex(e => e.id === id);
  if (idx !== -1) archive[idx] = updatedEntry; else archive.unshift(updatedEntry);
  saveArchive(archive);
  renderArchive();
  iHideEditBar();
  iCancelEdit();
  const body = document.getElementById('archiveBody');
  if (body && !body.classList.contains('open')) { body.classList.add('open'); document.getElementById('archiveArrow').textContent = '▲'; }
  alert(`✅ تم تحديث مقابلة "${studentName}" في الأرشيف بنجاح.`);
}
